// CONFIG
const CHAT_ID = 0; // sustituye por tu chat_id de Telegram

function fmtNum(n, d = 0) {
  return (n === null || n === undefined) ? '—' : Number(n).toFixed(d);
}

const ALARM_LABELS = {
  rfl_power_alarm: 'RFL Power',
  fwd_power_alarm: 'FWD Power',
  exc_power_alarm: 'EXC. Power',
  temp_combiner_alarm: 'Temp. Combiner',
  permanent_fail_alarm: 'Permanent Fail',
  ext_interlock_alarm: 'Ext. Interlock',
  control_unit_power_alarm: 'Control Unit Power',
};

const botState = $('GET bot-state (dashboard)').item.json;
const input = $input.first().json;

if (input.connected === undefined) {
  const raw = input.error !== undefined
    ? (typeof input.error === 'string' ? input.error : (input.error && input.error.message) || JSON.stringify(input.error))
    : 'error desconocido';
  return [{
    json: {
      action: 'dashboard',
      chatId: CHAT_ID,
      hasPinned: !!botState.pinnedMessageId,
      messageId: botState.pinnedMessageId || null,
      nextBotState: { ...botState },
      text: `⚠️ <b>Amplificador FM</b>\nNo se pudo consultar la API: ${raw}`,
    },
  }];
}

const status = input;
const events = [];
const wasConnected = botState.lastConnected === true;
const nowConnected = !!status.connected;

const lines = [];
lines.push('📻 <b>Amplificador FM — esRadio Albacete</b>');
if (nowConnected) {
  const target = status.transport === 'serial' ? status.device : `${status.host}:${status.port}`;
  lines.push(`🟢 Conectado (${status.transport}) — <code>${target}</code>`);
} else {
  lines.push(`⚪ Desconectado${status.last_error ? ` — ${status.last_error}` : ''}`);
}

const m = status.measurements;
const a = status.alarms;

if (m) {
  lines.push('');
  lines.push(`⚡ FWD: <b>${fmtNum(m.fwd_power_w)} W</b> · DC: ${fmtNum(m.vdc_volts, 1)} V`);
  const amps = m.idc_amps.map((c, i) => `A${i + 1}:${c}${m.current_alarms && m.current_alarms[i] ? '⚠️' : ''}`).join('  ');
  lines.push(`🔋 ${amps}`);
}

if (a) {
  const activas = Object.entries(ALARM_LABELS).filter(([k]) => a[k]).map(([, v]) => v);
  lines.push('');
  lines.push(activas.length ? `🚨 <b>Alarmas:</b> ${activas.join(', ')}` : '✅ Sin alarmas activas');
}

lines.push('');
lines.push(`<i>Actualizado: ${new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid' })}</i>`);

// Estado que hay que persistir tras este ciclo (pinnedMessageId se
// completa más adelante, tras mandar/editar el mensaje de Telegram).
const nextBotState = { ...botState, lastAlarms: a || botState.lastAlarms || null, lastConnected: nowConnected };

events.push({
  json: {
    action: 'dashboard',
    chatId: CHAT_ID,
    hasPinned: !!botState.pinnedMessageId,
    messageId: botState.pinnedMessageId || null,
    nextBotState,
    text: lines.join('\n'),
  },
});

if (a) {
  const prevAlarms = botState.lastAlarms || {};
  for (const [key, label] of Object.entries(ALARM_LABELS)) {
    const now = !!a[key];
    const before = !!prevAlarms[key];
    if (now && !before) {
      events.push({ json: { action: 'alerta', chatId: CHAT_ID, text: `🚨 <b>Alarma activada:</b> ${label}` } });
    } else if (!now && before) {
      events.push({ json: { action: 'alerta', chatId: CHAT_ID, text: `✅ <b>Alarma resuelta:</b> ${label}` } });
    }
  }
}

if (nowConnected && !wasConnected) {
  events.push({ json: { action: 'alerta', chatId: CHAT_ID, text: `🟢 <b>Conectado</b> al amplificador (${status.transport})` } });
} else if (!nowConnected && wasConnected) {
  events.push({ json: { action: 'alerta', chatId: CHAT_ID, text: `⚪ <b>Desconectado</b> del amplificador${status.last_error ? ` — ${status.last_error}` : ''}` } });
}

return events;

// Se ejecuta tras mandar/editar el mensaje del dashboard en Telegram.
// $json es la respuesta de Telegram (trae message_id); recuperamos el
// resto del estado ya calculado en "Preparar dashboard".
const prepared = $('Preparar dashboard').item.json;
const sentMessageId = $input.first().json.message_id;
return [{
  json: {
    ...prepared.nextBotState,
    pinnedMessageId: sentMessageId || prepared.messageId || null,
  },
}];

// CONFIG
const AUTHORIZED_USERS = [0]; // sustituye por los Telegram user IDs autorizados
const CONFIRM_TIMEOUT_MS = 60 * 1000;
const RISKY_LABELS = {
  arrancar: 'ARRANCAR el transmisor',
  parar: 'PARAR el transmisor',
  reset: 'resetear las alarmas',
};
const RISKY_ENDPOINTS = { arrancar: '/start', parar: '/stop', reset: '/reset' };

// Botones del dashboard (callback_data "menu:<clave>") -> comando + argumentos.
const MENU_ACTIONS = {
  subir: ['subir', []],
  bajar: ['bajar', []],
  maxima: ['maxima', []],
  pot40: ['potencia', ['40']],
  pot50: ['potencia', ['50']],
  pot60: ['potencia', ['60']],
  pot70: ['potencia', ['70']],
  pot80: ['potencia', ['80']],
  pot90: ['potencia', ['90']],
  estado: ['estado', []],
  alarmas: ['alarmas', []],
  log: ['log', []],
  arrancar: ['arrancar', []],
  parar: ['parar', []],
  reset: ['reset', []],
};

const botState = $('GET bot-state (cmd)').item.json;

// El resultado de un comando/botón se EDITA sobre el último que se mandó
// en ese chat (botState.lastReplyMessageIds), en vez de mandar mensaje
// nuevo cada vez. nextBotState viaja con el item para que, más adelante,
// el paso que guarda pendingConfirm no pise nada.
function reply(chatId, messageId, text, nextBotState) {
  const lastReplyMessageIds = (nextBotState || botState).lastReplyMessageIds || {};
  return {
    json: {
      action: 'reply',
      chatId,
      replyToMessageId: messageId,
      text,
      hasReplyPinned: !!lastReplyMessageIds[chatId],
      replyMessageId: lastReplyMessageIds[chatId] || null,
      nextBotState: nextBotState || botState,
    },
  };
}

function apiCall(httpMethod, httpPath, httpBody, replyKind, ctx, nextBotState) {
  return { json: { action: 'apiCall', httpMethod, httpPath, httpBody: httpBody || null, replyKind, nextBotState: nextBotState || botState, ...ctx } };
}

// Despacho compartido entre comandos escritos (/subir) y botones del dashboard.
function dispatchCommand(cmd, args, chatId, replyToMessageId, nextBotState) {
  const ctx = { chatId, replyToMessageId };
  switch (cmd) {
    case 'ayuda':
    case 'help':
      return [reply(chatId, replyToMessageId,
        '<b>Comandos disponibles</b>\n' +
        '/estado — resumen del amplificador\n' +
        '/alarmas — detalle de alarmas\n' +
        '/log [n] — últimas n lecturas (por defecto 5)\n' +
        '/subir — +50W\n' +
        '/bajar — −50W\n' +
        '/potencia 40|50|60|70|80|90 — preset de potencia\n' +
        '/maxima — potencia máxima\n' +
        '/arrancar — Start (pide confirmación)\n' +
        '/parar — Stop (pide confirmación)\n' +
        '/reset — reset de alarmas (pide confirmación)\n' +
        '/conectar host puerto — conectar por red (ser2net)\n' +
        '/conectar serial /dev/ttyUSB0 — conectar por puerto serie directo\n' +
        '/desconectar — cerrar la conexión\n\n' +
        'También puedes usar los botones debajo del dashboard.',
        nextBotState
      )];

    case 'estado':
      return [apiCall('GET', '/summary', null, 'estado', ctx, nextBotState)];

    case 'alarmas':
      return [apiCall('GET', '/alarms', null, 'alarmas', ctx, nextBotState)];

    case 'log': {
      const n = Math.max(1, Math.min(parseInt(args[0], 10) || 5, 50));
      return [apiCall('GET', `/history?limit=${n}`, null, 'log', ctx, nextBotState)];
    }

    case 'subir':
      return [apiCall('POST', '/power/up', null, 'subir', ctx, nextBotState)];

    case 'bajar':
      return [apiCall('POST', '/power/down', null, 'bajar', ctx, nextBotState)];

    case 'potencia': {
      const pct = parseInt(args[0], 10);
      if (![40, 50, 60, 70, 80, 90].includes(pct)) {
        return [reply(chatId, replyToMessageId, 'Uso: /potencia 40|50|60|70|80|90', nextBotState)];
      }
      return [apiCall('POST', '/power/set', { percent: pct }, 'potencia', { ...ctx, pct }, nextBotState)];
    }

    case 'maxima':
      return [apiCall('POST', '/power/max', null, 'maxima', ctx, nextBotState)];

    case 'conectar': {
      let body;
      if (args[0] === 'serial') {
        if (!args[1]) return [reply(chatId, replyToMessageId, 'Uso: /conectar serial [device]', nextBotState)];
        body = { device: args[1] };
      } else {
        const [host, port] = args;
        if (!host || !port) return [reply(chatId, replyToMessageId, 'Uso: /conectar [ip] [puerto]  ó  /conectar serial [device]', nextBotState)];
        body = { host, port: parseInt(port, 10) };
      }
      return [apiCall('POST', '/connect', body, 'conectar', ctx, nextBotState)];
    }

    case 'desconectar':
      return [apiCall('POST', '/disconnect', null, 'desconectar', ctx, nextBotState)];

    case 'arrancar':
    case 'parar':
    case 'reset': {
      const nonce = String(Date.now());
      const withPending = { ...(nextBotState || botState), pendingConfirm: { action: cmd, nonce, expiresAt: Date.now() + CONFIRM_TIMEOUT_MS } };
      return [{
        json: {
          action: 'sendConfirm',
          chatId,
          replyToMessageId,
          text: `⚠️ ¿Seguro que quieres <b>${RISKY_LABELS[cmd]}</b>? Caduca en ${CONFIRM_TIMEOUT_MS / 1000}s.`,
          confirmData: `confirm:${nonce}`,
          cancelData: `cancel:${nonce}`,
          nextBotState: withPending,
        },
      }];
    }

    default:
      return [reply(chatId, replyToMessageId, `Comando no reconocido: /${cmd}. Usa /ayuda.`, nextBotState)];
  }
}

const update = $input.first().json;

// ---------- Callback (botones: confirmar/cancelar, o menú del dashboard) ----------
if (update.callback_query) {
  const cb = update.callback_query;
  const fromId = cb.from.id;
  const chatId = cb.message.chat.id;
  const messageId = cb.message.message_id;
  const queryId = cb.id;
  const data = String(cb.data || '');

  const ack = { json: { action: 'callbackAck', queryId } };

  if (!AUTHORIZED_USERS.includes(fromId)) {
    return [ack, { json: { action: 'editConfirm', chatId, messageId, text: '🔒 No autorizado.', nextBotState: botState } }];
  }

  // Botones del dashboard: misma lógica que un comando escrito, respondiendo
  // como mensaje nuevo (no se toca el propio mensaje del dashboard).
  if (data.startsWith('menu:')) {
    const mapped = MENU_ACTIONS[data.slice('menu:'.length)];
    if (!mapped) return [ack];
    const [cmd, args] = mapped;
    return [ack, ...dispatchCommand(cmd, args, chatId, messageId, botState)];
  }

  // Confirmar/Cancelar de una acción de riesgo pendiente
  const pending = botState.pendingConfirm;
  const [kind, nonce] = data.split(':');

  if (!pending || pending.nonce !== nonce || Date.now() > pending.expiresAt) {
    return [ack, { json: { action: 'editConfirm', chatId, messageId, text: '⌛ Confirmación caducada o inválida. Repite el comando.', nextBotState: botState } }];
  }

  const clearedState = { ...botState, pendingConfirm: null };

  if (kind === 'cancel') {
    return [ack, { json: { action: 'editConfirm', chatId, messageId, text: `❎ ${RISKY_LABELS[pending.action]} — cancelado.`, nextBotState: clearedState } }];
  }

  return [ack, apiCall('POST', RISKY_ENDPOINTS[pending.action], null, 'confirmExec', {
    chatId, messageId, pendingActionLabel: RISKY_LABELS[pending.action],
  }, clearedState)];
}

// ---------- Mensaje de texto ----------
const msg = update.message;
if (!msg || !msg.text) return [];

const fromId = msg.from.id;
const chatId = msg.chat.id;
const messageId = msg.message_id;
const text = msg.text.trim();

if (!AUTHORIZED_USERS.includes(fromId)) {
  return [reply(chatId, messageId, '🔒 No autorizado.', botState)];
}

const [cmdRaw, ...args] = text.split(/\s+/);
const cmd = cmdRaw.toLowerCase().replace(/^\//, '').split('@')[0];

return dispatchCommand(cmd, args, chatId, messageId, botState);

// Guarda pendingConfirm (y cualquier otro cambio ya calculado) justo
// después de "Procesar comando", antes de seguir enrutando la
// respuesta. $json aquí es la respuesta del PUT; recuperamos el resto
// desde el nodo IF anterior (que solo deja pasar el item, sin tocarlo).
return [{ json: $('¿Es respuesta de callback?').item.json }];

const input = $input.first().json;
const ctx = $('Restaurar tras guardar pendingConfirm').item.json;
const isConfirm = ctx.replyKind === 'confirmExec';
const nextBotState = ctx.nextBotState || {};

function extractErrorDetail(errVal) {
  const raw = typeof errVal === 'string' ? errVal : (errVal && errVal.message) || JSON.stringify(errVal);
  try {
    const match = raw.match(/\{.*\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      if (parsed.detail) return parsed.detail;
    }
  } catch (e) { /* no era JSON, se usa el texto tal cual */ }
  return raw;
}

const ALARM_LABELS = {
  rfl_power_alarm: 'RFL Power', fwd_power_alarm: 'FWD Power', exc_power_alarm: 'EXC. Power',
  temp_combiner_alarm: 'Temp. Combiner', permanent_fail_alarm: 'Permanent Fail',
  ext_interlock_alarm: 'Ext. Interlock', control_unit_power_alarm: 'Control Unit Power',
};

let text;

if (input.error !== undefined) {
  const detail = extractErrorDetail(input.error);
  text = isConfirm ? `❌ Error al ${ctx.pendingActionLabel}: ${detail}` : `❌ Error: ${detail}`;
} else {
  const data = input;
  switch (ctx.replyKind) {
    case 'estado':
      text = data.text;
      break;
    case 'alarmas': {
      const activas = Object.entries(ALARM_LABELS).filter(([k]) => data[k]).map(([, v]) => v);
      text = activas.length ? `🚨 Alarmas activas: ${activas.join(', ')}` : '✅ Sin alarmas activas';
      break;
    }
    case 'log': {
      if (!data.points || !data.points.length) {
        text = 'Sin lecturas en el histórico todavía.';
      } else {
        const lines = data.points.map(p => {
          const m = p.measurements;
          return `${p.timestamp} — FWD ${m ? m.fwd_power_w : '—'}W, DC ${m ? m.vdc_volts : '—'}V`;
        });
        text = `<b>Últimas ${data.points.length} lecturas:</b>\n` + lines.join('\n');
      }
      break;
    }
    case 'subir':
      text = `⬆️ Potencia subida (${data.raw_hex}).`;
      break;
    case 'bajar':
      text = `⬇️ Potencia bajada (${data.raw_hex}).`;
      break;
    case 'potencia':
      text = `🎚️ Potencia fijada al ${ctx.pct}% (${data.raw_hex}).`;
      break;
    case 'maxima':
      text = `🔺 Potencia máxima fijada (${data.raw_hex}).`;
      break;
    case 'conectar': {
      const target = data.transport === 'serial' ? data.device : `${data.host}:${data.port}`;
      text = `🔌 Conectado — ${target} (${data.transport}).`;
      break;
    }
    case 'desconectar':
      text = '🔌 Desconectado.';
      break;
    case 'confirmExec':
      text = `✅ ${ctx.pendingActionLabel} — hecho (${data.raw_hex || data.ack_hex || 'ok'}).`;
      break;
    default:
      text = JSON.stringify(data);
  }
}

if (isConfirm) {
  return [{ json: { action: 'editConfirm', chatId: ctx.chatId, messageId: ctx.messageId, text, nextBotState } }];
}

const lastReplyMessageIds = nextBotState.lastReplyMessageIds || {};
return [{
  json: {
    action: 'reply',
    chatId: ctx.chatId,
    replyToMessageId: ctx.replyToMessageId,
    text,
    hasReplyPinned: !!lastReplyMessageIds[ctx.chatId],
    replyMessageId: lastReplyMessageIds[ctx.chatId] || null,
    nextBotState,
  },
}];

// Se ejecuta tras mandar/editar el mensaje de respuesta en Telegram.
// Toma el nextBotState que ya trae el item (de "Procesar comando" o de
// "Formatear respuesta de API", según el camino) y solo le añade el
// message_id nuevo para ese chat.
const src = $('¿Hay mensaje de respuesta fijado?').item.json;
const sent = $input.first().json;
const chatId = (sent.chat && sent.chat.id) || src.chatId;
const messageId = sent.message_id;

const nextBotState = { ...(src.nextBotState || {}) };
nextBotState.lastReplyMessageIds = { ...(nextBotState.lastReplyMessageIds || {}) };
if (chatId !== undefined && messageId !== undefined) {
  nextBotState.lastReplyMessageIds[chatId] = messageId;
}

return [{ json: nextBotState }];
